SELECT COUNT(*) AS valid_orders
FROM orders
WHERE order_status IN ('approved', 'invoiced', 'processing', 'shipped', 'delivered');

WITH payment_orders AS (
  SELECT DISTINCT order_id FROM order_payments
), item_orders AS (
  SELECT DISTINCT order_id FROM order_items
)
SELECT
  (SELECT COUNT(*) FROM payment_orders p LEFT JOIN item_orders i USING (order_id) WHERE i.order_id IS NULL) AS payment_records_no_order_items,
  (SELECT COUNT(*) FROM item_orders i LEFT JOIN payment_orders p USING (order_id) WHERE p.order_id IS NULL) AS order_items_no_payment_records;
